export const RoleRoleScopeKeyToLabel = {
  'Global': 'Global',
  'Workspace': 'Workspace'
} as const;
export type RoleRoleScopeKey = keyof typeof RoleRoleScopeKeyToLabel;

export const RoleStatusKeyToLabel = {
  'Active': 'Active',
  'Inactive': 'Inactive'
} as const;
export type RoleStatusKey = keyof typeof RoleStatusKeyToLabel;

export interface Role {
  /**
   * @displayName Role ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName RoleName
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  roleName: string;
  /**
   * @displayName Description
   * @validationRule Required for create/update operations
   */
  description: string;
  /**
   * @displayName RoleCode
   * @validationRule Required for create/update operations
   */
  roleCode: string;
  /**
   * @displayName RoleScope
   * @validationRule Required for create/update operations
   */
  roleScopeKey: RoleRoleScopeKey;
  /**
   * @displayName Status
   * @validationRule Required for create/update operations
   */
  statusKey: RoleStatusKey;
}

export const _Role = 'Role' as const;